function treeFields(depth) {
  let inner = 'object { ... on Blob { oid text isTruncated } }';
  for (let i = 0; i < depth; i++)
    inner = `object { ... on Blob { oid text isTruncated } ... on Tree { entries { name type ${inner} } } }`;
  return inner;
}

