=== calendar/data.js ===
     1	// The calendar's model: the local mirror in, entries and occurrences out.
     2	//
     3	// Two rules run through all of this:
     4	//   * The path is never the source of truth for a date - frontmatter `start` is. After a move
     5	//     or an override the two legitimately disagree, so nothing here parses a filename.
     6	//   * rrule.js works in UTC. An all-day rule is anchored at UTC midnight and read back with
     7	//     getUTC*(); calling getDate() on it returns the previous day east of UTC.
     8	import { parse, serialize } from '../shared/md.js';
     9	import { RRule } from '../shared/vendor/rrule.mjs';
    10	import { allFiles } from '../shared/store.js';
    11	import { write, remove, drain } from '../shared/github.js';
    12	
    13	export const ROOT = 'calendar';
    14	const UNKNOWN_COLOR = '#9aa5b1';          // group not in groups.md renders grey
    15	
    16	const pad = n => String(n).padStart(2, '0');
    17	
    18	// ---- dates -------------------------------------------------------------------------------
    19	// A bare date (2026-04-18) is all-day and is never run through a timezone. A timestamp is an
    20	// instant and belongs in the viewer's local day.
    21	
    22	export const isAllDay = v => !String(v).includes('T');
    23	export const localKey = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    24	const utcKey = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
    25	export const todayKey = () => localKey(new Date());
    26	
    27	// The day cell an entry falls in.
    28	function keyOf(start) {
    29	  const s = String(start);
    30	  if (isAllDay(s)) return s.slice(0, 10);
    31	  const d = new Date(s);
    32	  return isNaN(d) ? s.slice(0, 10) : localKey(d);
    33	}
    34	
    35	// Minutes from local midnight, or null for an all-day item (which sorts first).
    36	function minutesOf(start) {
    37	  const s = String(start);
    38	  if (isAllDay(s)) return null;
    39	  const d = new Date(s);
    40	  return isNaN(d) ? null : d.getHours() * 60 + d.getMinutes();
    41	}
    42	
    43	export function timeLabel(start) {
    44	  const m = minutesOf(start);
    45	  return m === null ? '' : `${pad(Math.floor(m / 60))}:${pad(m % 60)}`;
    46	}
    47	
    48	const instant = d => d.toISOString().replace(/\.\d{3}Z$/, 'Z');
    49	
    50	// The occurrence id used by `recurrence-id`, `exdate` and `rdate`: the occurrence's own start
    51	// value, in the same value type as the series start.
    52	const occIdOf = (d, allDay) => allDay ? utcKey(d) : instant(d);
    53	
    54	const list = v => v == null ? [] : Array.isArray(v) ? v : [v];
    55	
    56	// ---- the model ---------------------------------------------------------------------------
    57	
    58	export async function loadModel() {
    59	  return buildModel(await allFiles(ROOT + '/'));
    60	}
    61	
    62	// Pure, so it can be exercised from node against the same files the browser mirrors.
    63	export function buildModel(files) {
    64	  const groups = {}, dated = [], rules = [], overrides = new Map();
    65	  for (const f of files) {
    66	    if (!f.path.endsWith('.md') || f.text == null) continue;
    67	    const { data, body } = parse(f.text);
    68	    if (data.conflictOf) continue;               // a conflict copy would render twice
    69	    if (f.path === `${ROOT}/groups.md`) { Object.assign(groups, data.groups || {}); continue; }
