     9	    r.onupgradeneeded = () => {
    10	      const d = r.result;
    11	      d.createObjectStore('kv');                             // config, sync metadata
    12	      d.createObjectStore('files', { keyPath: 'path' });     // { path, text, oid }
    13	      d.createObjectStore('queue', { autoIncrement: true }); // pending writes
    14	    };
