   119	    type: data.type === 'task' ? 'task' : 'event',
   120	    group: data.group ?? '',
   121	    done: data.done === true,
   122	    location: data.location ?? '',
   123	    allDay: isAllDay(start),
   124	    start,
   125	    end: data.end == null ? '' : String(data.end),
   126	    dayKey: keyOf(start),
   127	    minutes: minutesOf(start)
   128	  };
   129	}
   130	
   131	function expandRule(rule, overrides, fromKey, toKey, out) {
   132	  const seriesStart = String(rule.data.start ?? '');
   133	  const allDay = isAllDay(seriesStart);
   134	  const rr = ruleOf(rule.data);
   135	  if (!rr) return;
   136	
   137	  // The range is local days; rrule answers in UTC. A day of padding either side covers the
   138	  // offset, and the dayKey test below drops whatever falls outside after conversion.
   139	  const from = new Date(Date.parse(`${fromKey}T00:00:00Z`) - 86400000);
   140	  const to = new Date(Date.parse(`${toKey}T00:00:00Z`) + 2 * 86400000);
   141	  if (isNaN(from) || isNaN(to)) return;
   142	
   143	  const ids = new Set(rr.between(from, to, true).map(d => occIdOf(d, allDay)));
   144	  for (const v of list(rule.data.rdate)) ids.add(String(v));
   145	  // An exdate may be written as a bare date even for a timed series; that skips the day.
   146	  const ex = new Set(list(rule.data.exdate).map(String));
