   148	  const dur = durationOf(rule.data);
   149	  for (const id of ids) {
   150	    if (ex.has(id) || ex.has(id.slice(0, 10))) continue;
   151	    const ov = overrides.get(`${rule.id}|${id}`);
   152	    if (ov?.data.status === 'cancelled') continue;
   153	
   154	    // The occurrence as the rule alone defines it, then the override's keys on top. Keeping
   155	    // the pristine form is what lets a save record only the keys that genuinely differ.
   156	    const base = { ...rule.data, start: id, end: dur != null ? shift(id, dur) : undefined };
   157	    delete base.exdate; delete base.rdate;       // belong to the series, not the occurrence
   158	    const data = { ...base, ...(ov?.data || {}) };
   159	    data.start = String(data.start); if (data.end != null) data.end = String(data.end);
   160	
   161	    const o = occurrence(rule, {
   162	      data, base,
   163	      body: ov && ov.body.trim() ? ov.body : rule.body,
   164	      series: rule, recId: id, override: ov || null
   165	    });
