   169	
   170	// An RRULE string with no DTSTART line, anchored on `start`. UTC midnight for an all-day rule.
   171	function ruleOf(data) {
   172	  const s = String(data.start ?? '');
   173	  const dtstart = new Date(isAllDay(s) ? `${s.slice(0, 10)}T00:00:00Z` : s);
   174	  if (isNaN(dtstart)) return null;
   175	  try { return new RRule({ ...RRule.parseString(String(data.recurrence)), dtstart }); }
   176	  catch { return null; }
   177	}
   178	
   179	// There is no `duration` key: it is end - start. Days for all-day, milliseconds for an instant.
   180	function durationOf(data) {
   181	  if (data.end == null || data.start == null) return null;
   182	  const a = String(data.start), b = String(data.end);
   183	  if (isAllDay(a) !== isAllDay(b)) return null;
   184	  if (isAllDay(a)) return Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86400000);
   185	  const ms = Date.parse(b) - Date.parse(a);
   186	  return isNaN(ms) ? null : ms;
   187	}
   188	
   189	function shift(start, dur) {
   190	  if (isAllDay(start)) return utcKey(new Date(Date.parse(`${start}T00:00:00Z`) + dur * 86400000));
