   192	}
   193	
   194	// ---- paths ------------------------------------------------------------------------------
   195	
   196	const ALPHABET = 'REDACTED';
   197	
   198	// 4 random characters, not a counter: two devices creating entries offline on the same day
   199	// must never mint the same name.
   200	function rand4() {
   201	  const b = new Uint8Array(4);
   202	  crypto.getRandomValues(b);
   203	  return [...b].map(n => ALPHABET[n % ALPHABET.length]).join('');
   204	}
   205	
   206	function slug(title) {
   207	  const s = String(title ?? '').toLowerCase().normalize('NFKD')
   208	    .replace(/[̀-ͯ]/g, '')
   209	    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24).replace(/-+$/, '');
   210	  return s || 'entry';
   211	}
   212	
   213	// A rule lives in recurring/ because an open-ended rule must render in months it was not
   214	// created in, and there is no month folder to find it under. Everything else goes in the date
   215	// tree, named from the UTC components of `start` so the name mirrors the stored string.
   216	export function pathFor(data, id = rand4()) {
   217	  if (data.recurrence) return `${ROOT}/recurring/${slug(data.title)}-${id}.md`;
   218	  const s = String(data.start ?? data['recurrence-id'] ?? '');
   219	  if (isAllDay(s)) {
   220	    const [y, m, d] = s.slice(0, 10).split('-');
   221	    return `${ROOT}/${y}/${m}/${y}-${m}-${d}-0000-${id}.md`;
   222	  }
   223	  const t = new Date(s);
   224	  const y = t.getUTCFullYear(), m = pad(t.getUTCMonth() + 1), d = pad(t.getUTCDate());
   225	  return `${ROOT}/${y}/${m}/${y}-${m}-${d}-${pad(t.getUTCHours())}${pad(t.getUTCMinutes())}-${id}.md`;
   226	}
   227	
   228	// The 4 random characters, so a move keeps the entry's identity.
   229	export const idTail = path => path.replace(/\.md$/, '').split('-').pop();
   230	
   231	// RFC 5545 naming, ordered as the samples are. serialize() drops empty keys rather than
   232	// writing `None`, which a parser would hand back as the string "None".
   233	const ORDER = ['series', 'recurrence-id', 'title', 'type', 'start', 'end', 'done', 'group',
   234	  'location', 'recurrence', 'exdate', 'rdate', 'alerts', 'participants', 'status'];
   235	
   236	function order(data) {
   237	  const out = {};
   238	  for (const k of ORDER) if (data[k] !== undefined) out[k] = data[k];
   239	  for (const k of Object.keys(data)) if (!ORDER.includes(k)) out[k] = data[k];
   240	  return out;
   241	}
   242	
   243	// Pure: what a write would put in the repo. Used by the write path and by the round-trip test.
   244	export const entryFile = (data, body, path) =>
   245	  ({ path: path || pathFor(data), text: serialize(order(data), body || '') });
   246	
   247	// ---- writes -----------------------------------------------------------------------------
   248	// Everything goes through github.js write()/remove() and then drain(): one drain is one
   249	// commit, so a move - delete plus create, because the date is in the path - cannot be half
   250	// applied.
   251	
   252	export async function createEntry(data, body) {
   253	  const f = entryFile(data, body);
   254	  await write(f.path, f.text);
