   256	  return f.path;
   257	}
   258	
   259	// Moves the file when `start` or `recurrence` changed where it belongs. Overrides pass
   260	// move:false - their path legitimately disagrees with their start and nothing may move them.
   261	export async function updateEntry(path, data, body, { move = true } = {}) {
   262	  let target = move ? pathFor(data, idTail(path)) : path;
   263	  // A rule file's name is permanent: override files reference it through `series`, so
   264	  // retitling must not rename it. Only gaining or losing the rule moves it.
   265	  if (path.startsWith(`${ROOT}/recurring/`) && target.startsWith(`${ROOT}/recurring/`)) target = path;
   266	  const f = entryFile(data, body, target);
   267	  if (target !== path) await remove(path);
   268	  await write(f.path, f.text);
   269	  await drain(`calendar: edit ${data.title || 'entry'}`);
   270	  return f.path;
   271	}
   272	
   273	export async function deleteEntry(path) {
   274	  await remove(path);
   275	  await drain(`calendar: delete ${path.split('/').pop()}`);
   276	}
   277	
   278	// ---- occurrences of a series ------------------------------------------------------------
   279	
   280	// A plain skip, where there is nothing to record: exdate on the rule file.
   281	export async function skipOccurrence(occ) {
   282	  const ex = list(occ.seriesData.exdate).map(String);
   283	  if (!ex.includes(occ.recId)) ex.push(occ.recId);
   284	  ex.sort();
   285	  await updateEntry(occ.seriesPath, { ...occ.seriesData, exdate: ex }, occ.seriesBody, { move: false });
   286	}
   287	
   288	// Anything that happens to a single occurrence is an override file in the date tree holding
   289	// only the keys that differ. The rule file is never rewritten, and since each override is a
   290	// fresh path it cannot conflict even when two devices do it offline.
   291	export async function saveOverride(occ, data, body) {
   292	  const diff = { series: occ.seriesId, 'recurrence-id': occ.recId };
