   294	    if (k === 'recurrence' || k === 'exdate' || k === 'rdate') continue;   // the series owns these
   295	    if (same(v, occ.base[k])) continue;
   296	    diff[k] = v;
   297	  }
   298	  const ownBody = body != null && body.trim() !== (occ.seriesBody || '').trim() ? body : '';
