   306	}
   307	
   308	// Drop the override; the occurrence goes back to following the series.
   309	async function clearOverride(occ) {
   310	  if (occ.override) await deleteEntry(occ.path);
   311	}
   312	
   313	const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);

