     1	// One IndexedDB for all apps. Same origin across /mine/ and /mine/<app>/, so the settings
     2	// written by the main app are readable from every subfolder. Verified on iOS and Android.
     3	const NAME = 'mine', VERSION = 1;
     4	let opening;
     5	
     6	function db() {
     7	  return opening ||= new Promise((res, rej) => {
     8	    const r = indexedDB.open(NAME, VERSION);
     9	    r.onupgradeneeded = () => {
    10	      const d = r.result;
    11	      d.createObjectStore('kv');                             // config, sync metadata
    12	      d.createObjectStore('files', { keyPath: 'path' });     // { path, text, oid }
    13	      d.createObjectStore('queue', { autoIncrement: true }); // pending writes
    14	    };
    15	    r.onsuccess = () => res(r.result);
    16	    r.onerror = () => rej(r.error);
    17	  });
    18	}
    19	
    20	async function run(store, mode, fn) {
    21	  const d = await db();
    22	  return new Promise((res, rej) => {
    23	    const t = d.transaction(store, mode), q = fn(t.objectStore(store));
    24	    t.onerror = () => rej(t.error);
    25	    if (q) { q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error); }
    26	    else t.oncomplete = () => res();
    27	  });
    28	}
    29	
    30	export const getKV = k => run('kv', 'readonly', s => s.get(k));
    31	export const setKV = (k, v) => run('kv', 'readwrite', s => s.put(v, k));
    32	
    33	export const getConfig = () => getKV('config');
    34	export const setConfig = c => setKV('config', c);
    35	
    36	export const getFile = path => run('files', 'readonly', s => s.get(path));
    37	export const putFile = f => run('files', 'readwrite', s => s.put(f));
    38	export const delFile = path => run('files', 'readwrite', s => s.delete(path));
    39	export const allFiles = async prefix =>
    40	  (await run('files', 'readonly', s => s.getAll()))
    41	    .filter(f => !prefix || f.path.startsWith(prefix));
    42	
    43	export const enqueue = item => run('queue', 'readwrite', s => s.add(item));
    44	export const queued = () => run('queue', 'readonly', s => s.getAll());
    45	export const queuedCount = () => run('queue', 'readonly', s => s.count());
    46	export const clearQueue = () => run('queue', 'readwrite', s => s.clear());
    47	
    48	// Request persistent storage. Granted without a prompt in an installed app on both
    49	// iOS and Android; without it, iOS evicts storage after ~7 days idle.
    50	export async function persist() {
    51	  try { return await navigator.storage.persisted() || await navigator.storage.persist(); }
    52	  catch { return false; }
    53	}

