     1	import yaml from './vendor/js-yaml.mjs';
     2	
     3	const FM = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;
     4	
     5	// CORE_SCHEMA, never DEFAULT: the default schema parses `start: 2026-04-18` into a JS Date
     6	// at UTC midnight, which is the all-day off-by-one-day bug the format exists to avoid.
     7	export function parse(text) {
     8	  const m = text.match(FM);
     9	  if (!m) return { data: {}, body: text };
    10	  return {
    11	    data: yaml.load(m[1], { schema: yaml.CORE_SCHEMA }) || {},
    12	    body: text.slice(m[0].length)
    13	  };
    14	}
    15	
    16	export function serialize(data, body = '') {
    17	  const lines = [];
    18	  for (const [k, v] of Object.entries(data)) {
    19	    if (v === undefined || v === null || v === '') continue;   // omit, never "None"
    20	    if (Array.isArray(v)) {
    21	      if (!v.length) continue;
    22	      lines.push(`${k}:`, ...v.map(i => `  - ${scalar(i)}`));
    23	    } else {
    24	      lines.push(`${k}: ${scalar(v)}`);
    25	    }
    26	  }
    27	  return `---\n${lines.join('\n')}\n---\n\n${body.replace(/^\n+/, '')}`;
    28	}
    29	
    30	const PLAIN = /^[A-Za-z0-9][A-Za-z0-9 _.:+/@-]*$/;
    31	const LOOKS_TYPED = /^(true|false|null|~|-?\d+(\.\d+)?)$/i;
    32	
    33	function scalar(v) {
    34	  if (typeof v === 'boolean' || typeof v === 'number') return String(v);
    35	  const s = String(v);
    36	  const safe = PLAIN.test(s) && !/: |\s$/.test(s) && !LOOKS_TYPED.test(s);
    37	  return safe ? s : JSON.stringify(s);   // valid YAML double-quoted scalar
    38	}

