   148	    });
   149	    await run('Pull it back', async () => `${(await pull()).changed} file(s) reconciled`);
   150	    add('Round-trip complete').className = 'done';
   151	  } catch {
   152	    /* the failing step already says why */
   153	  }
   154	});
