   158	function registerSW() {
   159	  if (!navigator.serviceWorker) return;
   160	  navigator.serviceWorker.register('./sw.js', { type: 'module', scope: './' }).then(reg => {
   161	    const offer = () => { $('#update').hidden = false; };
   162	    if (reg.waiting && navigator.serviceWorker.controller) offer();
   163	    reg.addEventListener('updatefound', () => {
   164	      const w = reg.installing;
   165	      w?.addEventListener('statechange', () => {
   166	        if (w.state === 'installed' && navigator.serviceWorker.controller) offer();
   167	      });
   168	    });
   169	    $('#reload').addEventListener('click', () => {
   170	      reg.waiting?.postMessage('skip-waiting');
   171	      navigator.serviceWorker.addEventListener('controllerchange',
   172	        () => location.reload(), { once: true });
   173	    });
   174	  }).catch(() => { /* an app that cannot cache still works online */ });
   175	}
