=== calendar/style.css ===
     1	/* Calendar. Phone first: the desktop grid is the enhancement, not the other way round.
     2	   A month cell is ~50px wide on a phone, so entry rows are neither readable nor tappable -
     3	   there the cells carry group-coloured dots and a tap opens a sheet. */
     4	
     5	/* An id or class rule for display beats the UA stylesheet's [hidden], so #cal and the
     6	   modal would both render while still carrying the attribute. */
     7	[hidden] { display: none !important; }
     8	
     9	:root { --cell: 3.1rem; --today: #1f66d0; }
    10	@media (prefers-color-scheme: dark) { :root { --today: #6ea8ff; } }
    11	
    12	body { max-width: none; padding: 0; padding-bottom: env(safe-area-inset-bottom); }
    13	#cal { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }
    14	
    15	/* ---- top pane ---- */
    16	.topbar {
    17	  position: sticky; top: 0; z-index: 5;
    18	  display: flex; align-items: center; gap: .35rem;
    19	  padding: max(.5rem, env(safe-area-inset-top)) .6rem .5rem;
    20	  background: var(--bg); border-bottom: 1px solid var(--line);
    21	}
    22	.topbar .spacer { flex: 1; }
    23	.nav {
    24	  width: auto; min-width: 2.4rem; min-height: 2.4rem; margin: 0; padding: .3rem .55rem;
    25	  font-size: 1.1rem; line-height: 1; font-weight: 500;
    26	  color: var(--fg); background: var(--soft); border: 0; border-radius: .5rem;
    27	}
    28	.nav.wide { font-size: .85rem; padding: .5rem .7rem; }
    29	.period {
    30	  width: auto; margin: 0; padding: .45rem .6rem; font-size: 1rem; font-weight: 600;
    31	  color: var(--fg); background: none; border: 0; white-space: nowrap;
    32	}
    33	.caret { margin-left: .3rem; font-size: .7rem; opacity: .6; }
    34	#groups-btn, #today { display: none; }
    35	#menu-btn { display: inline-block; }
    36	
    37	/* ---- week header + grid ---- */
    38	.weekhead {
    39	  display: grid; grid-template-columns: repeat(7, 1fr);
    40	  padding: .35rem .25rem 0; font-size: .7rem; font-weight: 600;
    41	  color: var(--muted); text-align: center; text-transform: uppercase; letter-spacing: .04em;
    42	}
    43	.weekhead span.we { color: var(--today); }
    44	
    45	.grid {
    46	  display: grid; grid-template-columns: repeat(7, 1fr);
    47	  gap: 1px; padding: .25rem; flex: 1;
    48	}
    49	.day {
    50	  display: flex; flex-direction: column; align-items: stretch; gap: .15rem;
    51	  min-height: var(--cell); padding: .2rem .15rem;
    52	  text-align: left; font: inherit; color: var(--fg);
    53	  background: var(--bg); border: 0; border-radius: .35rem; cursor: pointer;
    54	}
    55	.day.we { background: var(--soft); }
    56	.day.out { opacity: .38; }
    57	.num {
    58	  align-self: center; min-width: 1.6rem; padding: .12rem 0;
    59	  font-size: .8rem; font-variant-numeric: tabular-nums; text-align: center;
    60	  color: var(--muted); border-radius: 999px;
    61	}
    62	.day.today .num { color: #fff; background: var(--today); font-weight: 700; }
    63	
    64	/* phone: dots */
    65	.dots { display: flex; flex-wrap: wrap; justify-content: center; align-content: flex-start; gap: 3px; }
    66	.dot { width: 7px; height: 7px; border-radius: 999px; background: var(--c); }
    67	.dot.open { box-shadow: inset 0 0 0 7px var(--c); }
    68	.dot.done { background: none; box-shadow: inset 0 0 0 1.5px var(--c); }
    69	.more { font-size: .6rem; color: var(--muted); line-height: 7px; }
    70	
    71	/* desktop: entry rows */
    72	.rows { display: none; flex-direction: column; gap: 2px; overflow: hidden; }
    73	.erow {
    74	  display: flex; align-items: center; gap: .3rem;
    75	  padding: .1rem .25rem; font-size: .72rem; line-height: 1.25;
    76	  background: var(--soft); border-radius: .25rem; cursor: pointer;
    77	}
    78	.erow .bar { flex: none; width: 3px; align-self: stretch; min-height: .9rem; border-radius: 2px; background: var(--c); }
    79	.erow .when { flex: none; color: var(--muted); font-variant-numeric: tabular-nums; }
    80	.erow .what { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    81	.erow.done .what { text-decoration: line-through; color: var(--muted); }
    82	.tick {
    83	  flex: none; width: 1rem; height: .8rem; margin: 0; padding: 0;
    84	  background: none; border: 1.5px solid var(--muted); border-radius: 2px; cursor: pointer;
    85	}
    86	.erow.done .tick { background: var(--c); border-color: var(--c); }
    87	
    88	.sync { padding: .4rem .7rem; margin: 0; font-size: .75rem; }
    89	
    90	/* ---- popovers, sheets, modal ---- */
    91	.scrim { position: fixed; inset: 0; z-index: 8; background: rgb(0 0 0 / .35); }
    92	.pop {
    93	  position: fixed; z-index: 10; width: min(19rem, calc(100vw - 1.5rem));
    94	  padding: .7rem; background: var(--bg);
    95	  border: 1px solid var(--line); border-radius: .7rem; box-shadow: 0 8px 30px rgb(0 0 0 / .25);
    96	}
    97	.pop-head { display: flex; align-items: center; gap: .3rem; margin-bottom: .5rem; }
    98	.pop-head .spacer { flex: 1; }
    99	.pop-title { width: auto; margin: 0; padding: .3rem .4rem; font-weight: 600; color: var(--fg); background: none; border: 0; }
   100	.link { width: auto; margin: 0; padding: .2rem .4rem; font-size: .78rem; font-weight: 500; color: var(--today); background: none; border: 0; }
   101	
   102	.pick-body { display: grid; gap: 2px; }
   103	.pick-body.days { grid-template-columns: repeat(7, 1fr); }
   104	.pick-body.years { grid-template-columns: repeat(3, 1fr); }
   105	.pick-body .wh { font-size: .62rem; color: var(--muted); text-align: center; text-transform: uppercase; }
   106	.pk {
   107	  width: auto; margin: 0; padding: .45rem .1rem; font-size: .8rem; font-weight: 500;
   108	  color: var(--fg); background: none; border: 0; border-radius: .35rem;
   109	}
   110	.pk.out { color: var(--muted); opacity: .55; }
   111	.pk.now { color: #fff; background: var(--today); font-weight: 700; }
   112	.pick-body.years .pk { padding: .7rem .1rem; }
   113	
   114	.groups-list { display: flex; flex-direction: column; gap: .1rem; }
   115	.glab { display: flex; align-items: center; gap: .55rem; padding: .5rem .3rem; font-size: .9rem; color: var(--fg); cursor: pointer; }
   116	.glab input { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; }
   117	.swatch { flex: none; width: .85rem; height: .85rem; border-radius: 999px; background: var(--c); }
   118	
   119	.sheet {
   120	  position: fixed; inset: auto 0 0; z-index: 10; max-height: 82dvh; overflow-y: auto;
   121	  padding: .3rem 1rem calc(1rem + env(safe-area-inset-bottom));
   122	  background: var(--bg); border-radius: 1rem 1rem 0 0; box-shadow: 0 -4px 30px rgb(0 0 0 / .3);
   123	}
   124	.sheet-grip { width: 2.4rem; height: 4px; margin: .5rem auto .6rem; background: var(--line); border-radius: 2px; }
   125	.sheet h2 { margin: .2rem 0 .7rem; font-size: 1.05rem; }
