  const pen = iconBtn('pen', `Edit ${g.label || name}`);
  pen.addEventListener('click', () => { editing = name; build(); });
  const del = iconBtn('trash', `Delete ${g.label || name}`);
  del.addEventListener('click', () => removeGroup(name, g));
