import io, re, collections
VOID = {'area','base','br','col','embed','hr','img','input','link','meta','source','track','wbr','path'}
class P(HTMLParser):
    def __init__(self): super().__init__(convert_charrefs=True); self.stack=[]; self.err=[]; self.ids=collections.Counter()
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if 'id' in d: self.ids[d['id']] += 1
        if tag not in VOID: self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack: self.err.append(f'stray </{tag}> at {self.getpos()}')
        elif self.stack[-1][0] != tag:
            self.err.append(f'</{tag}> at {self.getpos()} closes <{self.stack[-1][0]}> opened at {self.stack[-1][1]}')
            self.stack.pop()
        else: self.stack.pop()
