    p = P(); p.feed(io.open(f, encoding='utf-8').read())
    dup = [i for i,n in p.ids.items() if n>1]
    print(f, '->', 'balanced' if not p.err and not p.stack else f'ERRORS {p.err} unclosed={p.stack}',
          f'| duplicate ids: {dup}' if dup else '')
