import io, re
for f in ('style.css', 'calendar/style.css'):
    s = io.open(f, encoding='utf-8').read()
    s2 = re.sub(r'/\*.*?\*/', '', s, flags=re.S)
    print(f, '-> braces', 'balanced' if s2.count('{') == s2.count('}') else f"UNBALANCED {s2.count('{')}/{s2.count('}')}")
# every class the JS creates should have a rule somewhere (a missing one is usually a typo)
css = io.open('calendar/style.css', encoding='utf-8').read() + io.open('style.css', encoding='utf-8').read() \
      + io.open('calendar/index.html', encoding='utf-8').read()
used = set()
for f in ('app.js','ui.js','views.js','kanban.js','popup.js','settings.js'):
    src = io.open('calendar/'+f, encoding='utf-8').read()
    for m in re.findall(r"el\('[a-z0-9]+', *'([^']*)'", src) + re.findall(r"el\('[a-z0-9]+', *`([^`]*)`", src):
        for c in re.split(r'[\s$]+', m):
            c = c.strip('{}')
            if c and not any(ch in c for ch in '?:()'): used.add(c)
missing = sorted(c for c in used if '.'+c not in css)
print('classes created in JS with no CSS rule:', missing or 'none')
PY

