cat > calendar/__harness.html <<'EOF'
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>harness</title></head>
<body>
<pre id="log"></pre>
<script type="module">
const log = [];
const out = () => { document.getElementById('log').textContent = log.join('\n'); };
const say = m => { log.push(m); out(); };
addEventListener('error', e => say('PAGE ERROR: ' + (e.error?.stack || e.message)));
addEventListener('unhandledrejection', e => say('REJECTION: ' + (e.reason?.stack || e.reason)));

// Seed the mirror the way a bootstrap would, then boot the real calendar page in place.
const seed = await (await fetch('../__seed.json')).json();
await new Promise((res, rej) => {
  const r = indexedDB.open('mine', 1);
  r.onupgradeneeded = () => {
    const d = r.result;
    d.createObjectStore('kv');
    d.createObjectStore('files', { keyPath: 'path' });
    d.createObjectStore('queue', { autoIncrement: true });
  };
  r.onsuccess = () => {
    const d = r.result;
    const t = d.transaction(['kv', 'files'], 'readwrite');
    t.objectStore('kv').put({ owner: 'o', repo: 'r', branch: 'main', token: 't' }, 'config');
    for (const f of seed) t.objectStore('files').put(f);
    for (const [k, v] of JSON.parse(localStorage.getItem('prefs') || '[]'))
      t.objectStore('kv').put(v, k);
    t.oncomplete = res;
    t.onerror = () => rej(t.error);
  };
  r.onerror = () => rej(r.error);
});

const html = await (await fetch('index.html')).text();
const doc = new DOMParser().parseFromString(html, 'text/html');
for (const n of [...doc.body.children]) if (n.tagName !== 'SCRIPT') document.body.append(n);
for (const href of ['../style.css', 'style.css']) {
  const l = document.createElement('link');
  l.rel = 'stylesheet'; l.href = href;
  document.head.append(l);
}
say('markup in place');
await import('./app.js');
say('app.js imported');
await new Promise(r => setTimeout(r, 300));

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const check = (what, got, want) =>
  say(`${String(got) === String(want) ? 'ok  ' : 'FAIL'} ${what}: ${got}${String(got) === String(want) ? '' : ` (want ${want})`}`);
const click = s => { const n = $(s); if (!n) return say(`FAIL no such node ${s}`); n.click(); };
const mode = async m => { click(`[data-mode="${m}"]`); await new Promise(r => setTimeout(r, 120)); };

say('--- boot ---');
check('setup screen hidden', $('#needs-setup').hidden, true);
check('calendar shown', $('#cal').hidden, false);
check('viewport', `${innerWidth}x${innerHeight}`, `${innerWidth}x${innerHeight}`);
say(`period: "${$('#period-label').textContent}"`);
say(`sync: "${$('#sync').textContent}"`);

say('--- month ---');
check('month cells are whole weeks', $$('#view .day').length % 7, 0);
say(`month cells: ${$$('#view .day').length}, entry lines: ${$$('#view .eline').length}`);
say(`lines: ${$$('#view .eline .what').map(n => n.textContent).join(' | ')}`);
check('weekday header', $$('#view .weekhead span').map(n => n.textContent).join(''),
  $$('#view .weekhead span').map(n => n.textContent).join(''));
say(`weekhead: ${$$('#view .weekhead span').map(n => n.textContent).join(' ')}`);
check('tick buttons on tasks', $$('#view .tick').length > 0, true);
check('no week gutter by default', $$('#view .wk').length, 0);

for (const m of ['W', 'D', 'Y', 'K']) {
  await mode(m);
  say(`--- ${m} --- period: "${$('#period-label').textContent}"`);
  if (m === 'W' || m === 'D') {
    check(`${m}: hour rows`, $$('#view .hr').length, 24);
    check(`${m}: day columns`, $$('#view .tcol').length, m === 'W' ? 7 : 1);
    say(`${m}: timed blocks ${$$('#view .tev').length}, all-day ${$$('#view .adcell .eline').length}`);
  }
  if (m === 'Y') {
    check('Y: twelve months', $$('#view .ymonth').length, 12);
    check('Y: coloured days', $$('#view .yday[style*="background"]').length > 0, true);
  }
  if (m === 'K') {
    check('K: three columns', $$('#view .kcol').length, 3);
    say(`K: headers ${$$('#view .khead').map(h => h.textContent).join(' | ')}`);
    say(`K: cards ${$$('#view .kcard .ktitle').map(n => n.textContent).join(' | ')}`);
    say(`K: chips ${$$('#view .kcard .chip').map(n => n.textContent).join(' ')}`);
  }
}

say('--- the entry popup ---');
await mode('M');
click('#add');
await new Promise(r => setTimeout(r, 80));
check('popup open', $('#popup').hidden, false);
say(`icon bar: ${$$('#f-icons .ib').map(b => b.getAttribute('aria-label')).join(' | ')}`);
check('event is the default', $('[data-type]') === null, true);
check('task row hidden for an event', $('#f-task').hidden, true);
click('#f-icons .ib');                                   // T = task
await new Promise(r => setTimeout(r, 50));
check('task row shown', $('#f-task').hidden, false);
say(`stage pressed: ${$$('[data-stage]').filter(b => b.getAttribute('aria-pressed') === 'true').map(b => b.dataset.stage)}`);
say(`start: ${$('#f-start-date').value} ${$('#f-start-time').value}  end: ${$('#f-end-date').value} ${$('#f-end-time').value}`);

say('--- a field sub-popup ---');
$$('#f-icons .ib').find(b => b.getAttribute('aria-label') === 'Repeat').click();
await new Promise(r => setTimeout(r, 50));
check('sub-popup open', $('#sub').hidden, false);
say(`repeat options: ${$$('#sub-body select')[0] ? [...$$('#sub-body select')[0].options].map(o => o.textContent).join(' / ') : 'NONE'}`);
const sel = $$('#sub-body select')[0];
sel.value = 'weekly';
sel.dispatchEvent(new Event('change'));
click('#sub-ok');
await new Promise(r => setTimeout(r, 50));
check('sub-popup closed', $('#sub').hidden, true);
say(`detail rows: ${$$('#f-rows .frow').map(r => r.textContent.replace(/\s+/g, ' ')).join(' | ')}`);
say(`repeat icon lit: ${$$('#f-icons .ib').find(b => b.getAttribute('aria-label') === 'Repeat')?.className}`);
click('#f-icons .ib[aria-label="Close and discard"]');
check('popup closed', $('#popup').hidden, true);

say('--- editing an existing entry ---');
$('#view .eline').click();
await new Promise(r => setTimeout(r, 80));
check('popup open on an entry', $('#popup').hidden, false);
say(`title: "${$('#f-title').value}"  path: ${$('#f-path').textContent}`);
say(`rows: ${$$('#f-rows .frow .flab').map(n => n.textContent).join(', ')}`);
click('#f-icons .ib[aria-label="Close and discard"]');

say('--- settings ---');
click('#gear');
await new Promise(r => setTimeout(r, 80));
check('settings open', $('#settings-sheet').hidden, false);
say(`rows: ${$$('#settings-body .srow .slab').map(n => n.textContent).join(' | ')}`);
say(`groups: ${$$('#settings-body .grow .gname').map(n => n.textContent).join(', ')}`);
click('#settings-close');

say('--- the filter ---');
click('#filter-btn');
await new Promise(r => setTimeout(r, 60));
say(`filter: ${$$('#filter-body .glab span:last-child').map(n => n.textContent).join(', ')}`);
click('#scrim');

say('DONE ' + (log.some(l => l.startsWith('FAIL') || l.includes('ERROR') || l.includes('REJECTION')) ? 'WITH FAILURES' : 'CLEAN'));
</script>
</body></html>
