python3 -m http.server 8731 --bind 127.0.0.1 >/dev/null 2>&1 &
sleep 1
chromium --headless --disable-gpu --no-sandbox --window-size=1200,900 \
  --user-data-dir="$SCRATCH/chrome" --virtual-time-budget=9000 \
  --dump-dom http://127.0.0.1:8731/calendar/__harness.html 2>"$SCRATCH/chrome.log" \
