    src = io.open(f, encoding='utf-8').read()
    for m in re.findall(r'^export (?:async )?(?:function|const|let|class)\s+(\w+)', src, re.M):
        exports[(f, m)] = 0
    for m in re.findall(r'^export \{([^}]*)\}', src, re.M):
        for n in m.split(','):
            exports[(f, n.strip())] = 0
